import React from 'react';
import { useData } from '../DataContext';
import { Card, Container, Row, Col } from 'react-bootstrap'; // Importar componentes do Bootstrap
import '../Estilo/Detalhes.css'; // Caminho para o CSS atualizado

function Detalhes() {
  const { data } = useData();

  return (
    <Container className="mt-5">
      <h1 className="text-center mb-4">Detalhes do Cadastro</h1>
      <Row>
        {data.length === 0 ? (
          <Col>
            <p className="text-center">Nenhum dado cadastrado.</p>
          </Col>
        ) : (
          data.map((item, index) => (
            <Col key={index} sm={12} md={6} lg={4}>
              <Card className="mb-4">
                <Card.Body>
                  <Card.Title>{item.nomeCompleto}</Card.Title>
                  <Card.Subtitle className="mb-2 text-muted">{item.telefone}</Card.Subtitle>
                  <Card.Text>
                    <strong>Data de Nascimento:</strong> {item.dataNascimento}
                  </Card.Text>
                </Card.Body>
              </Card>
            </Col>
          ))
        )}
      </Row>
    </Container>
  );
}

export default Detalhes;
